"use client";
/* eslint-disable @next/next/no-img-element */

import { type ReactNode } from "react";
import { CHEMICAL_KINETICS_PARTS } from "./part-metadata";
import { BlockMath, InlineMath } from "react-katex";
import "katex/dist/katex.min.css";

/**
 * Chemical Kinetics — JEE Advanced master chapter
 *
 * Runtime dependencies: React, Tailwind CSS, react-katex and katex.
 * All diagrams are original inline SVGs; no external image asset is required.
 */

type CardTone = "navy" | "cyan" | "violet" | "amber" | "emerald" | "rose";

type ConceptCardProps = {
  title: string;
  tone?: CardTone;
  eyebrow?: string;
  children: ReactNode;
};

type WorkedExampleProps = {
  number: number;
  title: string;
  difficulty?: "Foundation" | "JEE Main+" | "JEE Advanced";
  concept: string;
  question: ReactNode;
  solution: ReactNode;
  answer: ReactNode;
};

type ChapterSectionProps = {
  id: string;
  index: string;
  eyebrow: string;
  title: string;
  intro: ReactNode;
  children: ReactNode;
};

type SourcePageRecord = {
  page: number;
  title: string;
  range: string;
  density: string;
  text: string;
};

type TextbookExtensionRecord = {
  number: number;
  title: string;
  core: string;
  formula: string;
  trap: string;
  visual: string;
  paragraphs: readonly string[];
  tasks: readonly string[];
};


const toneClass: Record<CardTone, string> = {
  navy: "border-[var(--border-strong)]/80 bg-[var(--background)]/70",
  cyan: "border-cyan-400/25 bg-cyan-400/[0.055]",
  violet: "border-violet-400/25 bg-violet-400/[0.055]",
  amber: "border-amber-400/25 bg-amber-400/[0.055]",
  emerald: "border-emerald-400/25 bg-emerald-400/[0.055]",
  rose: "border-rose-400/25 bg-rose-400/[0.055]",
};

const badgeClass: Record<CardTone, string> = {
  navy: "border-slate-600 bg-[var(--surface)] text-[var(--text-body)]",
  cyan: "border-cyan-400/25 bg-cyan-400/10 text-cyan-200",
  violet: "border-violet-400/25 bg-violet-400/10 text-violet-200",
  amber: "border-amber-400/25 bg-amber-400/10 text-amber-200",
  emerald: "border-emerald-400/25 bg-emerald-400/10 text-emerald-200",
  rose: "border-rose-400/25 bg-rose-400/10 text-rose-200",
};

const toc = [
  ["scope", "01", "Scope, language and notation"],
  ["stoichiometry", "02", "Stoichiometry and extent"],
  ["rate", "03", "Rate of reaction"],
  ["measurement", "04", "Experimental measurement"],
  ["rate-law", "05", "Rate law, order and molecularity"],
  ["integrated", "06", "Integrated rate laws"],
  ["order-methods", "07", "Finding reaction order"],
  ["special-methods", "08", "Pressure, volume and optical methods"],
  ["reversible", "09", "Reversible reactions"],
  ["parallel", "10", "Parallel reactions"],
  ["consecutive", "11", "Consecutive reactions"],
  ["temperature", "12", "Temperature and Arrhenius kinetics"],
  ["collision", "13", "Collision and transition-state theories"],
  ["mechanism", "14", "Mechanisms, RDS and steady state"],
  ["catalysis", "15", "Catalysis and enzyme kinetics"],
  ["advanced", "16", "Advanced extensions"],
  ["formula-atlas", "17", "Formula atlas and JEE traps"],
  ["practice", "18", "Integrated worked examples"],
  ["modified-bank", "19", "96 additional modified solved problems"],
  ["textbook-extension", "20", "50-page textbook extension"],
  ["source-coverage", "21", "Complete 259-page source audit"],
] as const;

function K({ children }: { children: string }) {
  return <InlineMath math={children} />;
}

function KB({ children }: { children: string }) {
  return <BlockMath math={children} />;
}

function ConceptCard({ title, tone = "navy", eyebrow, children }: ConceptCardProps) {
  return (
    <article className={`rounded-3xl border p-5 shadow-[0_18px_70px_-40px_rgba(0,0,0,0.85)] backdrop-blur-sm sm:p-6 ${toneClass[tone]}`}>
      {eyebrow ? (
        <div className={`mb-3 inline-flex rounded-full border px-2.5 py-1 text-[11px] font-bold uppercase tracking-[0.17em] ${badgeClass[tone]}`}>
          {eyebrow}
        </div>
      ) : null}
      <h3 className="text-lg font-semibold tracking-tight text-white sm:text-xl">{title}</h3>
      <div className="mt-3 space-y-3 text-[15px] leading-7 text-[var(--text-body)]">{children}</div>
    </article>
  );
}

function FormulaCard({ title, children, note }: { title: string; children: ReactNode; note?: ReactNode }) {
  return (
    <div className="overflow-hidden rounded-3xl border border-cyan-300/20 bg-gradient-to-br from-cyan-300/[0.08] via-slate-950/80 to-violet-400/[0.08] shadow-[0_24px_80px_-48px_rgba(34,211,238,0.5)]">
      <div className="border-b border-white/10 px-5 py-3 text-xs font-bold uppercase tracking-[0.18em] text-cyan-200">{title}</div>
      <div className="formula-scroll overflow-x-auto px-4 py-5 text-slate-100 sm:px-6">{children}</div>
      {note ? <div className="border-t border-white/10 px-5 py-3 text-sm leading-6 text-[var(--text-muted)]">{note}</div> : null}
    </div>
  );
}

function ExamTrap({ children }: { children: ReactNode }) {
  return (
    <div className="rounded-2xl border border-rose-400/25 bg-rose-400/[0.065] px-4 py-3 text-sm leading-6 text-rose-100">
      <span className="mr-2 font-black uppercase tracking-[0.13em] text-rose-300">JEE trap</span>
      {children}
    </div>
  );
}

function KeyIdea({ children }: { children: ReactNode }) {
  return (
    <div className="rounded-2xl border border-amber-300/25 bg-amber-300/[0.06] px-4 py-3 text-sm leading-6 text-amber-50">
      <span className="mr-2 font-black uppercase tracking-[0.13em] text-amber-200">Key idea</span>
      {children}
    </div>
  );
}

function DataTable({ headers, rows }: { headers: ReactNode[]; rows: ReactNode[][] }) {
  return (
    <div className="overflow-x-auto rounded-2xl border border-white/10">
      <table className="min-w-full border-collapse text-left text-sm">
        <thead className="bg-white/[0.055] text-[var(--foreground)]">
          <tr>{headers.map((header, i) => <th key={i} className="border-b border-white/10 px-4 py-3 font-semibold">{header}</th>)}</tr>
        </thead>
        <tbody className="divide-y divide-white/[0.075] text-[var(--text-body)]">
          {rows.map((row, r) => (
            <tr key={r} className="transition hover:bg-white/[0.025]">
              {row.map((cell, c) => <td key={c} className="whitespace-nowrap px-4 py-3 align-top">{cell}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function FigureFrame({ title, caption, children }: { title: string; caption: ReactNode; children: ReactNode }) {
  return (
    <figure className="overflow-hidden rounded-3xl border border-white/10 bg-[var(--background)]/75">
      <div className="border-b border-white/10 px-5 py-3 text-sm font-semibold text-[var(--foreground)]">{title}</div>
      <div className="overflow-x-auto p-3 sm:p-5">{children}</div>
      <figcaption className="border-t border-white/10 px-5 py-3 text-sm leading-6 text-[var(--text-muted)]">{caption}</figcaption>
    </figure>
  );
}

function ChapterSection({ id, index, eyebrow, title, intro, children }: ChapterSectionProps) {
  return (
    <section id={id} className="scroll-mt-24 border-t border-white/[0.08] py-14 sm:py-18">
      <div className="mb-8 grid gap-4 lg:grid-cols-[92px_1fr] lg:gap-7">
        <div className="text-5xl font-black tracking-[-0.06em] text-white/[0.12] sm:text-6xl">{index}</div>
        <div>
          <p className="text-xs font-bold uppercase tracking-[0.22em] text-cyan-300">{eyebrow}</p>
          <h2 className="mt-2 text-3xl font-bold tracking-[-0.035em] text-white sm:text-4xl">{title}</h2>
          <div className="mt-4 max-w-4xl text-base leading-8 text-[var(--text-body)]">{intro}</div>
        </div>
      </div>
      <div className="space-y-6">{children}</div>
    </section>
  );
}

function WorkedExample({ number, title, difficulty = "JEE Advanced", concept, question, solution, answer }: WorkedExampleProps) {
  const difficultyClass = difficulty === "Foundation"
    ? "border-emerald-400/25 bg-emerald-400/10 text-emerald-200"
    : difficulty === "JEE Main+"
      ? "border-amber-400/25 bg-amber-400/10 text-amber-100"
      : "border-violet-400/25 bg-violet-400/10 text-violet-100";

  return (
    <details className="group overflow-hidden rounded-3xl border border-white/10 bg-[var(--background)]/70 shadow-[0_24px_100px_-60px_rgba(139,92,246,0.8)]" open={number <= 2}>
      <summary className="cursor-pointer list-none px-5 py-5 transition hover:bg-white/[0.025] sm:px-6">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex min-w-0 gap-4">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl border border-violet-300/20 bg-violet-400/10 font-bold text-violet-200">{number}</div>
            <div>
              <h3 className="text-lg font-semibold text-white sm:text-xl">{title}</h3>
              <p className="mt-1 text-sm leading-6 text-[var(--text-muted)]">{concept}</p>
            </div>
          </div>
          <span className={`rounded-full border px-3 py-1 text-xs font-bold ${difficultyClass}`}>{difficulty}</span>
        </div>
        <div className="mt-4 text-[15px] leading-7 text-[var(--foreground)]">{question}</div>
        <div className="mt-3 text-xs font-bold uppercase tracking-[0.16em] text-cyan-300 group-open:hidden">Open full solution</div>
      </summary>
      <div className="border-t border-white/10 px-5 py-5 sm:px-6">
        <div className="mb-3 text-xs font-black uppercase tracking-[0.18em] text-violet-300">Solution</div>
        <div className="space-y-3 text-[15px] leading-7 text-[var(--text-body)]">{solution}</div>
        <div className="mt-5 rounded-2xl border border-emerald-400/25 bg-emerald-400/[0.065] px-4 py-3 text-[15px] leading-7 text-emerald-100">
          <span className="mr-2 font-black uppercase tracking-[0.14em] text-emerald-300">Answer</span>
          {answer}
        </div>
      </div>
    </details>
  );
}

function ExtentProgressFigure() {
  return (
    <svg viewBox="0 0 900 330" className="mx-auto min-w-[660px] max-w-5xl" role="img" aria-label="Extent of reaction and stoichiometric progress">
      <defs>
        <linearGradient id="extentBg" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#071326"/><stop offset="1" stopColor="#0f172a"/></linearGradient>
        <marker id="extentArrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#67e8f9"/></marker>
      </defs>
      <rect x="8" y="8" width="884" height="314" rx="28" fill="url(#extentBg)" stroke="#334155"/>
      <text x="54" y="58" fill="#e2e8f0" fontSize="23" fontWeight="700">aA + bB → yY + zZ</text>
      <line x1="245" y1="104" x2="655" y2="104" stroke="#67e8f9" strokeWidth="4" markerEnd="url(#extentArrow)"/>
      <text x="310" y="89" fill="#a5f3fc" fontSize="16">progress by extent ξ</text>
      <g fontSize="18" fontWeight="650">
        <text x="82" y="155" fill="#fda4af">Reactants decrease</text>
        <text x="82" y="195" fill="#f8fafc">n<tspan baselineShift="sub" fontSize="13">A</tspan> = n<tspan baselineShift="sub" fontSize="13">A,0</tspan> − aξ</text>
        <text x="82" y="232" fill="#f8fafc">n<tspan baselineShift="sub" fontSize="13">B</tspan> = n<tspan baselineShift="sub" fontSize="13">B,0</tspan> − bξ</text>
        <text x="570" y="155" fill="#6ee7b7">Products increase</text>
        <text x="570" y="195" fill="#f8fafc">n<tspan baselineShift="sub" fontSize="13">Y</tspan> = n<tspan baselineShift="sub" fontSize="13">Y,0</tspan> + yξ</text>
        <text x="570" y="232" fill="#f8fafc">n<tspan baselineShift="sub" fontSize="13">Z</tspan> = n<tspan baselineShift="sub" fontSize="13">Z,0</tspan> + zξ</text>
      </g>
      <rect x="305" y="255" width="290" height="45" rx="15" fill="#22d3ee" fillOpacity="0.09" stroke="#22d3ee" strokeOpacity="0.4"/>
      <text x="450" y="284" textAnchor="middle" fill="#cffafe" fontSize="18">ξ = (nᵢ − nᵢ,0)/νᵢ</text>
    </svg>
  );
}

