function IntegratedPlotsFigure() {
  return (
    <svg viewBox="0 0 1000 410" className="mx-auto min-w-[820px] max-w-6xl" role="img" aria-label="Linear plots for zero first and second order reactions">
      <rect x="8" y="8" width="984" height="394" rx="28" fill="#07111f" stroke="#334155"/>
      {[
        { x: 55, label: "Zero order", y: "[A]", eq: "slope = −k", path: "M42 55 L270 270", color: "#22d3ee" },
        { x: 370, label: "First order", y: "ln[A]", eq: "slope = −k", path: "M42 55 L270 270", color: "#a78bfa" },
        { x: 685, label: "Second order", y: "1/[A]", eq: "slope = +k", path: "M42 270 L270 55", color: "#34d399" },
      ].map((p) => (
        <g key={p.label} transform={`translate(${p.x} 50)`}>
          <text x="150" y="0" textAnchor="middle" fill="#f8fafc" fontSize="20" fontWeight="700">{p.label}</text>
          <line x1="30" y1="290" x2="285" y2="290" stroke="#94a3b8" strokeWidth="2"/>
          <line x1="30" y1="290" x2="30" y2="35" stroke="#94a3b8" strokeWidth="2"/>
          <path d={p.path} transform="translate(0 0)" fill="none" stroke={p.color} strokeWidth="5"/>
          <text x="148" y="324" textAnchor="middle" fill="#cbd5e1" fontSize="15">t</text>
          <text transform="translate(4 170) rotate(-90)" textAnchor="middle" fill="#cbd5e1" fontSize="15">{p.y}</text>
          <text x="150" y="365" textAnchor="middle" fill={p.color} fontSize="16">{p.eq}</text>
        </g>
      ))}
    </svg>
  );
}

function ExperimentalMethodsFigure() {
  return (
    <svg viewBox="0 0 1000 410" className="mx-auto min-w-[820px] max-w-6xl" role="img" aria-label="Experimental methods for measuring reaction rate">
      <rect x="8" y="8" width="984" height="394" rx="28" fill="#07111f" stroke="#334155"/>
      <g fontFamily="inherit" textAnchor="middle">
        {[
          [145, 125, "Titration", "withdraw + quench", "#22d3ee"],
          [380, 125, "Gas pressure", "manometer / sensor", "#a78bfa"],
          [620, 125, "Optical", "absorbance / rotation", "#fbbf24"],
          [855, 125, "Conductance", "ions with time", "#34d399"],
        ].map(([x, y, a, b, c]) => (
          <g key={String(a)}>
            <circle cx={Number(x)} cy={Number(y)} r="78" fill={String(c)} fillOpacity="0.07" stroke={String(c)} strokeOpacity="0.45" strokeWidth="2"/>
            <text x={Number(x)} y={Number(y) - 7} fill="#f8fafc" fontSize="18" fontWeight="700">{String(a)}</text>
            <text x={Number(x)} y={Number(y) + 22} fill="#cbd5e1" fontSize="13">{String(b)}</text>
          </g>
        ))}
        <path d="M145 225 C145 280 300 315 500 315 C700 315 855 280 855 225" fill="none" stroke="#475569" strokeWidth="2" strokeDasharray="7 7"/>
        <text x="500" y="350" fill="#e2e8f0" fontSize="18" fontWeight="650">Choose an observable that maps uniquely to concentration or extent</text>
      </g>
    </svg>
  );
}

